    for (const action of actions) visitActionForCycles(action, visiting, done, [])
}

/** Parse action files once at the file-loading boundary. */
export function parseActionDefinitionFiles(files) {
    return files.map((file) => parseActionFile(file))
}

/** Validate and resolve a whole-project graph of structured action definitions. */
export function validateActionDefinitionGraph(entries, dependencies = {}) {
    const rawDefinitions = entries.map(({ definition, path }) => validateRawDefinition(definition, path, dependencies))
    const ids = new Set(BUILTIN_ACTIONS.map(({ id }) => id))
    const normalizedIds = new Map(BUILTIN_ACTIONS.map(({ id }) => [normalizeActionId(id), id]))
    for (const raw of rawDefinitions) {
        if (ids.has(raw.id)) throw fail(`Duplicate action id ${raw.id} in ${raw.sourcePath}`, 'duplicate-id', raw.sourcePath, 'id')
        const normalizedId = normalizeActionId(raw.id)
        const collidingId = normalizedIds.get(normalizedId)
        if (collidingId) {
            throw fail(
                `Action id ${raw.id} in ${raw.sourcePath} collides with ${collidingId} after normalization`,
                'normalized-id-collision',
                raw.sourcePath,
                'id',
            )
        }
        ids.add(raw.id)
        normalizedIds.set(normalizedId, raw.id)
    }

    const registry = new Map(BUILTIN_ACTIONS.map((action) => [action.id, action]))
    for (const raw of rawDefinitions) {
        registry.set(raw.id, {
            agent: raw.agent ?? null,
            appliesTo: raw.appliesTo ?? null,
            autoFinish: raw.autoFinish ?? null,
            builtin: false,
            command: raw.command ?? null,
            description: raw.description,
            icon: raw.icon ?? null,
            id: raw.id,
            label: raw.label,
            model: raw.model ?? null,
            needsWorkTree: raw.needsWorkTree,
            on: [],
            onAfter: [],
            onBefore: [],
            onState: raw.onState ?? null,
            phrases: raw.phrases,
            permissionMode: raw.permissionMode ?? null,
            prompt: raw.prompt ?? null,
            sourcePath: raw.sourcePath,
            thinkingLevel: raw.thinkingLevel ?? null,
            trackFileChanges: raw.trackFileChanges,
            streaming: raw.streaming,
            type: raw.type,
        })
    }

    for (const raw of rawDefinitions) {
        const action = registry.get(raw.id)
        action.onBefore = raw.onBefore.map((actionId, index) => resolveAction(actionId, registry, raw.sourcePath, 'onBefore', index))
        action.onAfter = raw.onAfter.map((actionId, index) => resolveAction(actionId, registry, raw.sourcePath, 'onAfter', index))
        action.on = raw.on.map(({ actionId, condition }, index) => ({
            action: resolveAction(actionId, registry, raw.sourcePath, 'on', index),
            actionId,
            condition,
        }))
    }

    const actions = [...BUILTIN_ACTIONS, ...rawDefinitions.map(({ id }) => registry.get(id))]
    detectCycles(actions)

    return actions
}

export function loadActionDefinitions(files, dependencies = {}) {
    return validateActionDefinitionGraph(parseActionDefinitionFiles(files), dependencies)
}

import { ACTION_APPLIES_TO_FIELDS, CUSTOM_PROMPT_ACTION_ID } from './action_types'
import type { ActionAppliesToField, ActionDefinition } from './action_types'
import type { Card, CardHeader, CardTypeConfig } from './data_types'
import { getCardIdPrefix } from './card_identifiers'

/** The kind of item an action entry point is attached to. */
export type ActionContextKind = 'card' | 'file' | 'folder' | 'merge-conflict' | 'project'

export type ActionContextFilterValueSource =
    'kind' | 'type' | 'state' | 'file' | 'folder' | 'worktree' | 'text'

export interface ActionContextFilterDescriptor {
    key: ActionAppliesToField
    label: string
    supportedContextKinds: ActionContextKind[]
    valueSource: ActionContextFilterValueSource
    validate: (value: string) => string | null
}

/**
 * The selected item an action is evaluated against. `appliesTo` keys are matched
 * field-by-field against this object, so every matchable property is a string.
 */
export interface ActionContext {
    /** Stable card identity used for activity ownership. */
    cardInternalId?: string
    /** Title of the selected card, used for placeholder resolution. */
    title?: string
    /** Card/file type derived from the id prefix, e.g. `feature`. */
    type?: string
    /** Card state / status, e.g. `design`. */
    state?: string
    /** Path to the markdown file, used for placeholder resolution. */
    file?: string
    /** Folder name for folder contexts. */
    folder?: string
    /** Selected conflicted repository-relative path. */
    conflictFile?: string
    /** Newline-separated conflicted repository-relative paths. */
    conflictFiles?: string
    /** Active desktop conflict session binding. */
    conflictSessionId?: string
    kind: ActionContextKind
    worktree?: string
    worktreeError?: string
    [key: string]: string | undefined
}

/**
 * Stable identity of the item an action runs against, used to match a popup to its
 * execution and conversation history. Mutable header fields (title, state, worktree)
 * are excluded on purpose: a run that edits its own card must keep the same identity.
 */
export function actionContextIdentity(context: ActionContext): string {
    if (context.kind === 'project') return 'project'
    if (context.kind === 'folder') return `folder�${context.folder ?? ''}`
    if (context.kind === 'merge-conflict') {
        return `merge-conflict�${context.conflictSessionId ?? ''}�${context.conflictFile ?? ''}`
    }

    return `${context.kind}�${context.cardInternalId ?? context.file ?? ''}`
}

/** Required-value validation shared by every applicability filter descriptor. */
export function validateActionContextFilterValue(value: string): string | null {
    return value.length > 0 ? null : 'Required value'
}

const ACTION_CONTEXT_FILTER_METADATA: Record<ActionAppliesToField, Omit<ActionContextFilterDescriptor, 'key'>> = {
    file: { label: 'Repository file', supportedContextKinds: ['card', 'file'], valueSource: 'file', validate: validateActionContextFilterValue },
    folder: { label: 'Repository folder', supportedContextKinds: ['folder'], valueSource: 'folder', validate: validateActionContextFilterValue },
    kind: { label: 'Target kind', supportedContextKinds: ['card', 'file', 'folder', 'merge-conflict', 'project'], valueSource: 'kind', validate: validateActionContextFilterValue },
    state: { label: 'Card state', supportedContextKinds: ['card', 'file'], valueSource: 'state', validate: validateActionContextFilterValue },
    type: { label: 'Context type', supportedContextKinds: ['card', 'file', 'folder'], valueSource: 'type', validate: validateActionContextFilterValue },
    worktree: { label: 'Worktree', supportedContextKinds: ['card', 'file', 'project'], valueSource: 'worktree', validate: validateActionContextFilterValue },
    worktreeError: { label: 'Worktree error', supportedContextKinds: ['card', 'file'], valueSource: 'text', validate: validateActionContextFilterValue },
}

export const ACTION_CONTEXT_FILTER_DESCRIPTORS: ActionContextFilterDescriptor[] = ACTION_APPLIES_TO_FIELDS.
